#include "market_comparison_plot.hpp"
#include <QPainter>
#include <QPainterPath>
#include <QWheelEvent>
#include <QMouseEvent>
#include <QJsonArray>
#include <QToolTip>
#include <cmath>
#include <algorithm>
namespace {int legendRows(const QWidget*w,const QJsonObject&frame){int rows=1,width=0;for(auto v:frame.value("series").toArray()){int next=w->fontMetrics().horizontalAdvance(v.toObject().value("name").toString())+22;if(width&&width+next>w->width()-80){++rows;width=0;}width+=next;}return rows;}QRectF area(const QWidget*w,const QJsonObject&frame){int left=65;for(auto s:frame["series"].toArray())for(auto v:s.toObject()["values"].toArray())if(v.isDouble()&&std::isfinite(v.toDouble()))left=std::max(left,w->fontMetrics().horizontalAdvance(QString::number(v.toDouble(),'f',2))+16);left=std::min(left,180);return QRectF(left,42,std::max(1,w->width()-left-25),std::max(1,w->height()-88-18*legendRows(w,frame)));}QJsonArray labels(QJsonObject f){return f.value(f.contains("dates")?"dates":"labels").toArray();}QColor color(QJsonObject row,int n,const QWidget*w){auto special=row.value("color").toString();if(special=="weighted")return w->palette().text().color();if(special=="leading")return QColor("#db9b1d");static const char*colors[]={"#d35f67","#4198d2","#3da58c","#9672cb","#d49a38","#4aaeb7","#a27a57","#cb6ca5"};return QColor(colors[n%8]);}}
MarketComparisonPlot::MarketComparisonPlot(QWidget*p):QWidget(p){setObjectName("comparisonPlot");setMinimumHeight(230);setMouseTracking(true);setFocusPolicy(Qt::StrongFocus);}
void MarketComparisonPlot::clamp(){int count=labels(frame).size();span=std::clamp(span,2.,double(std::max(2,count)));first=std::clamp(first,0.,std::max(0.,count-span));}
void MarketComparisonPlot::setFrame(const QJsonObject&value,bool preserve){
 bool had=!labels(frame).isEmpty();frame=value;hovered=-1;
 if(!preserve||!had||autoFit){first=0;span=std::max(2,int(labels(frame).size()));autoFit=true;}
 if(!pendingViewport.isEmpty()&&!labels(frame).isEmpty()){auto saved=pendingViewport;pendingViewport={};restoreViewport(saved);}
 clamp();update();
}
QJsonObject MarketComparisonPlot::saveViewport()const{return pendingViewport.isEmpty()?QJsonObject{{"version",2},{"first",first},{"span",span},{"autoFit",autoFit}}:pendingViewport;}
void MarketComparisonPlot::restoreViewport(const QJsonObject&value){
 if(!value.value("first").isDouble()||!value.value("span").isDouble()||!std::isfinite(value.value("first").toDouble())||!std::isfinite(value.value("span").toDouble())||value["span"].toDouble()<2)return;
 if(labels(frame).isEmpty()){pendingViewport=value;return;}
 const bool legacy=value["version"].toInt()!=2;
 // Old saves could capture the empty/loading frame's 2-slot clamp. They do not
 // distinguish deliberate zoom from that initialization artifact.
 autoFit=legacy?(value["span"].toDouble()<=3||labels(frame).first().toString().contains(':')||value["span"].toDouble()>=labels(frame).size()):value["autoFit"].toBool();
 first=autoFit?0:value["first"].toDouble();span=autoFit?labels(frame).size():value["span"].toDouble();clamp();update();
}
void MarketComparisonPlot::resetViewport(){pendingViewport={};autoFit=true;first=0;span=std::max(2,int(labels(frame).size()));clamp();update();emit viewportChanged();}
void MarketComparisonPlot::paintEvent(QPaintEvent*){QPainter p(this);p.setRenderHint(QPainter::Antialiasing);p.fillRect(rect(),palette().base());auto box=area(this,frame);auto dates=labels(frame);auto series=frame.value("series").toArray();auto ink=palette().text().color();p.setPen(ink);if(dates.isEmpty()||series.isEmpty()){p.drawText(box,Qt::AlignCenter|Qt::TextWordWrap,frame.value("emptyReason").toString("请选择至少两个指数或板块"));return;}int from=std::max(0,int(std::floor(first))),to=std::min(int(dates.size())-1,int(std::ceil(first+span-1)));double low=INFINITY,high=-INFINITY;for(auto v:series){auto row=v.toObject();if(row.value("hidden").toBool())continue;auto values=row.value("values").toArray();for(int n=from;n<=to&&n<values.size();++n)if(values[n].isDouble()&&std::isfinite(values[n].toDouble())){low=std::min(low,values[n].toDouble());high=std::max(high,values[n].toDouble());}}if(!std::isfinite(low)||!std::isfinite(high)){p.drawText(box,Qt::AlignCenter,"当前区间暂无数据");return;}double padding=std::max((high-low)*.08,.01);low-=padding;high+=padding;auto point=[&](int n,double value){return QPointF(box.left()+(n-first)/std::max(1.,span-1)*box.width(),box.bottom()-(value-low)/(high-low)*box.height());};const int yTicks=std::clamp(int(box.height()/28)+1,2,5);for(int n=0;n<yTicks;++n){double value=low+(high-low)*n/(yTicks-1);double y=point(from,value).y();p.setPen(QPen(palette().mid().color(),.6));p.drawLine(QPointF(box.left(),y),QPointF(box.right(),y));p.setPen(ink);p.drawText(QRectF(0,y-9,box.left()-8,18),Qt::AlignRight|Qt::AlignVCenter,QString::number(value,'f',2));}p.setPen(ink);const int ticks=box.width()>700?5:3;for(int j=0;j<ticks;++j){int n=from+(to-from)*j/(ticks-1);QString label=dates[n].toString();if(dates.size()==242&&from==0&&to==241&&j==(ticks-1)/2)label="11:30/13:00";double w=std::min(box.width(),double(p.fontMetrics().horizontalAdvance(label)+8));double x=point(n,low).x();p.drawText(QRectF(std::clamp(x-w/2,box.left(),box.right()-w),box.bottom()+7,w,22),Qt::AlignCenter,label);}p.drawText(QRectF(box.left(),3,box.width(),24),Qt::AlignLeft,frame.value("title").toString());p.save();p.setClipRect(box.adjusted(-2,-2,2,2));for(int s=0;s<series.size();++s){auto row=series[s].toObject();if(row.value("hidden").toBool())continue;auto values=row.value("values").toArray();QPainterPath path;bool started=false;for(int n=from;n<=to&&n<values.size();++n){if(!values[n].isDouble()||!std::isfinite(values[n].toDouble())){if(!frame.value("connectGaps").toBool())started=false;continue;}auto at=point(n,values[n].toDouble());if(!started){path.moveTo(at);started=true;}else path.lineTo(at);}p.setPen(QPen(color(row,s,this),row.value("width").toDouble(1.7),row.value("dashed").toBool()?Qt::DashLine:Qt::SolidLine));p.drawPath(path);}if(hovered>=from&&hovered<=to){p.setPen(QPen(ink,.7,Qt::DashLine));auto x=point(hovered,low).x();p.drawLine(QPointF(x,box.top()),QPointF(x,box.bottom()));}p.restore();int x=int(box.left()),y=int(box.bottom()+45);for(int s=0;s<series.size();++s){auto row=series[s].toObject();p.setPen(color(row,s,this));auto title=row.value("name").toString();int width=fontMetrics().horizontalAdvance(title)+22;if(x+width>this->width()-12&&x>box.left()){x=int(box.left());y+=18;}p.drawText(x,y,title);x+=width;} }
void MarketComparisonPlot::wheelEvent(QWheelEvent*event){auto box=area(this,frame);if(!box.contains(event->position())||labels(frame).size()<3){event->ignore();return;}autoFit=false;double fraction=std::clamp((event->position().x()-box.left())/box.width(),0.,1.);double anchor=first+fraction*(span-1);span*=event->angleDelta().y()>0?.78:1.28;clamp();first=anchor-fraction*(span-1);clamp();update();emit viewportChanged();event->accept();}
void MarketComparisonPlot::mousePressEvent(QMouseEvent*event){if(event->button()==Qt::LeftButton&&area(this,frame).contains(event->position())){dragging=true;pressed=event->position();pressedFirst=first;setCursor(Qt::ClosedHandCursor);event->accept();}else QWidget::mousePressEvent(event);}
void MarketComparisonPlot::mouseMoveEvent(QMouseEvent*event){auto box=area(this,frame);if(dragging){autoFit=false;first=pressedFirst-(event->position().x()-pressed.x())/box.width()*(span-1);clamp();update();emit viewportChanged();return;}auto dates=labels(frame);if(!box.contains(event->position())||dates.isEmpty()){hovered=-1;update();return;}hovered=std::clamp(int(std::round(first+(event->position().x()-box.left())/box.width()*(span-1))),0,int(dates.size())-1);QString text=dates[hovered].toString().toHtmlEscaped();for(auto v:frame.value("series").toArray()){auto row=v.toObject();auto values=row.value("values").toArray();QString value=hovered<values.size()&&values[hovered].isDouble()?QString::number(values[hovered].toDouble(),'f',6):QString("缺失");text+="<br>"+row.value("name").toString().toHtmlEscaped()+"："+value;}QToolTip::showText(event->globalPosition().toPoint(),text,this);update();}
void MarketComparisonPlot::mouseReleaseEvent(QMouseEvent*event){if(dragging){dragging=false;unsetCursor();event->accept();}else QWidget::mouseReleaseEvent(event);}
void MarketComparisonPlot::mouseDoubleClickEvent(QMouseEvent*){resetViewport();}
void MarketComparisonPlot::leaveEvent(QEvent*event){if(!dragging){hovered=-1;QToolTip::hideText();update();}QWidget::leaveEvent(event);}
